import { useEffect, useMemo, useState } from "react";
import {
  Button,
  Row,
  Col,
  Container,
  Alert,
  Card,
} from "react-bootstrap";
import { getAccount } from "../Data/api";
import { useNavigate } from "react-router-dom";
import useLocalStorage from "./useLocalStorage";

function Login() {
  const navigate = useNavigate();
  const [accounts, setAccounts] = useState([]);
const [email, setEmail] = useState([]);
  const [password, setPassword] = useState([]);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  const loadCourses = () => {
    getAccount()
      .then((data) => setAccounts(data))
      .catch(() => setError("Không thể tải danh sách khóa học."));
  };

  useEffect(() => {
    loadCourses();
  }, []);

  const filteredAccount = useMemo(() => {
    const keyword = search.trim();

    return accounts
      .filter((a) => {
        const matchesEmail = !keyword || a.email.startsWith(keyword);
        const matchesPassword = !keyword || a.password.startsWith(keyword);

        return matchesEmail && matchesEmail;
      })
  }, [accounts, search, email, password]);

  return (
    <Container className="py-4">

      <Row>
        {filteredAccount.map((account) => (
          <Col md={4} className="mb-2" key={account.id}>
            <Card>
              <Card.Body>
                <div style={{ display: "flex", flexDirection: "column" }}>
                  <div
                    style={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <p>{account.badge}</p>
                    <p>{account.category}</p>
                  </div>
                  <Card.Text>
                    {account.code}
                    <h5>{account.nameEn}</h5>
                    {account.nameVi}
                    <div className="text-muted small"></div>
                  </Card.Text>
                  <div
                    style={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <strong>Get started</strong>
                    <Button
                      onClick={() => navigate(`/syllabus`)}
                      variant="primary"
                    >
                      →
                    </Button>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default Login;
